// 실적이 비어 있고 target_date 가 이미 지난 D+1 행만 골라낸다.
// (D+2~D+4 예측은 해당 날짜가 D+1 로 다시 예측되므로, 채점은 D+1 만 사용해
//  horizon 간 중복 집계를 피한다.)
const rows = $input.all().map(i => i.json);
const today = new Date(); today.setHours(0,0,0,0);
const pending = rows.filter(r => {
  if (r.horizon !== 'D+1') return false;
  if (r.DA_actual !== '' && r.DA_actual != null) return false;
  const d = new Date(r.target_date);
  return d < today;
});
if (!pending.length) return [{ json: { skip: true, reason: 'no pending rows' } }];
return pending.map(r => ({ json: { ...r, skip: false } }));

// 예측행 + 실적가격 결합 → 채점 필드 계산
const pred = $('Find Pending Rows').all().map(i => i.json);
const settle = $input.all();
if (settle.length !== pred.length) {
  throw new Error(`정산 응답 ${settle.length}건 != 대기 예측행 ${pred.length}건. 순서 매칭이 어긋나면 다른 날짜에 실적이 붙는다 — 중단합니다.`);
}
const out = [];
for (let i = 0; i < pred.length; i++) {
  const s = $input.all()[i]?.json ?? {};
  const DA = Number(s.DA_avg ?? s.da ?? NaN);
  const RT = Number(s.RT_avg ?? s.rt ?? NaN);
  if (Number.isNaN(DA) || Number.isNaN(RT)) continue;
  const f = Number(pred[i].DA_fraction);
  const dart = RT - DA;
  out.push({ json: {
    ...pred[i],
    DA_actual: DA.toFixed(2),
    RT_actual: RT.toFixed(2),
    DART_actual: dart.toFixed(2),
    blended_cost: (f*DA + (1-f)*RT).toFixed(2),
    hit: ((f > 0.5) === (dart > 0)) ? 'Y' : 'N'
  }});
}
return out;

// 채점 완료된 D+1 행만 → /score 페이로드
const rows = $input.all().map(i => i.json)
  .filter(r => r.horizon === 'D+1' && r.DA_actual !== '' && r.DA_actual != null);
if (rows.length < 20) {
  return [{ json: { insufficient: true, n: rows.length } }];
}
return [{ json: { insufficient: false, payload: rows.map(r => ({
  date: r.target_date,
  DA_fraction: Number(r.DA_fraction),
  DA_actual: Number(r.DA_actual),
  RT_actual: Number(r.RT_actual)
})) } }];

// 최근 30일 vs 전체 비교 → 드리프트 판정 (경보용, 자동 튜닝 아님)
const s = $input.all()[0].json;
const det = s.detail || [];
const sorted = det.slice().sort((a,b) => new Date(a.date) - new Date(b.date));
const recent = sorted.slice(-30);
const mean = (a, k) => a.length ? a.reduce((x,r)=>x+Number(r[k]),0)/a.length : null;
const hitOf = a => a.length ? a.filter(r => (r.DA_fraction>0.5)===(r.DART>0)).length/a.length*100 : null;
const rHit = hitOf(recent), aHit = s.hit_rate_all;
const rVsRt = mean(recent, 'vs_rt');
// 경보 임계
//  * |DART|>=$20 적중률이 제1 지표다. walk-forward 531일에서 절약액의 대부분이 그 30일에서
//    나왔고, 그 구간에서만 모델이 '아무것도 안 하기'(=항상 RT, 40%)를 이겼다(60%).
//    전체 적중률은 항상 RT 쪽이 더 높아 판단 기준이 못 된다 — 큰 날을 맞히는지가 전부다.
//  * 표본이 얇으면(<10일) 판정하지 않는다. $20 초과일은 전체의 약 5~6% 밖에 안 된다.
const alerts = [];
if (s.n_big20 >= 10 && s.hit_rate_big20 !== null && s.hit_rate_big20 < 50)
  alerts.push(`[중요] 큰날(|DART|>=$20) 적중 ${s.hit_rate_big20}% — 손익이 걸린 구간에서 열위`);
if (s.vs_rt_big20 !== null && s.n_big20 >= 10 && s.vs_rt_big20 > 0)
  alerts.push(`[중요] 큰날 실현원가가 RT 대비 +$${Number(s.vs_rt_big20).toFixed(2)} 열위`);
if (rVsRt !== null && rVsRt > 1.0) alerts.push(`최근 30일 RT 대비 +$${rVsRt.toFixed(2)} 열위`);
if (s.hit_rate_big5 !== null && s.hit_rate_big5 < 45) alerts.push(`큰날(|DART|>=$5) 적중 ${s.hit_rate_big5}%`);
if (s.n_days >= 120 && Math.abs((rHit ?? 0) - aHit) > 15) alerts.push(`최근 적중률 편차 ${(rHit-aHit).toFixed(0)}p`);
return [{ json: {
  window_all_days: s.n_days,
  cost_blended: s.cost_blended, cost_all_rt: s.cost_all_rt, cost_all_da: s.cost_all_da,
  vs_rt: s.vs_rt, vs_da: s.vs_da, cost_std: s.cost_std,
  hit_rate_all: s.hit_rate_all, hit_rate_big5: s.hit_rate_big5, n_big5: s.n_big5,
  hit_rate_big20: s.hit_rate_big20, n_big20: s.n_big20, vs_rt_big20: s.vs_rt_big20,
  mean_da_fraction: s.mean_da_fraction,
  recent30_hit: rHit === null ? '' : rHit.toFixed(1),
  recent30_vs_rt: rVsRt === null ? '' : rVsRt.toFixed(3),
  alert: alerts.length ? alerts.join(' / ') : 'none'
}}];

