const res = $input.all()[0].json;
const m = $('Compute Drift Metrics').all()[0].json;
const text = (res.content||[]).filter(b=>b.type==='text').map(b=>b.text).join('\n').trim();
return [{ json: { logged_at: new Date().toISOString(), kind: 'weekly_lookback', ...m, commentary: text } }];
